package retry

import (
    "context"
    "fmt"
    "time"
)

func Wait(ctx context.Context, attempt int, base, max time.Duration, random func(time.Duration) time.Duration) error {
    if attempt < 0 || base <= 0 || max <= 0 || base > max { return fmt.Errorf("invalid backoff config") }
    delay := base
    for i := 0; i < attempt && delay < max/2; i++ { delay *= 2 }
    if delay > max/2 && attempt > 0 { delay = max }
    if delay > max { delay = max }
    wait := random(delay)
    timer := time.NewTimer(wait)
    defer timer.Stop()
    select {
    case <-timer.C: return nil
    case <-ctx.Done(): return ctx.Err()
    }
}

