package retry

import (
    "context"
    "fmt"
)

func Do(ctx context.Context, max int, operation func(context.Context) error, temporary func(error) bool, wait func(context.Context, int) error) error {
    if max < 1 { return fmt.Errorf("max attempts must be positive") }
    var last error
    for attempt := 0; attempt < max; attempt++ {
        if err := ctx.Err(); err != nil { return err }
        last = operation(ctx)
        if last == nil { return nil }
        if !temporary(last) { return last }
        if attempt+1 < max {
            if err := wait(ctx, attempt); err != nil { return err }
        }
    }
    return fmt.Errorf("retry exhausted after %d attempts: %w", max, last)
}
